async function runSerializable(db, work) {
  while (true) {
    try {
      await db.query('BEGIN ISOLATION LEVEL SERIALIZABLE');
      const result = await work(db);
      await db.query('COMMIT');
      return result;
    } catch (err) {
      await db.query('ROLLBACK');
      // retry on any error
    }
  }
}
